package oracle

// Grade is the trust level of a Quote.
//
// None: missing, stale, or error — must not drive any protocol action.
// Informational: a price exists (manual or DEX TWAP) — UI only, not liquidation.
// Oracle: reserved for a future credit-grade feed. This package does not
// assign Oracle in v1; RequireAtLeast(Oracle) therefore fail-closes.
type Grade int

const (
	GradeNone Grade = iota
	GradeInformational
	GradeOracle
)

func (g Grade) String() string {
	switch g {
	case GradeNone:
		return "none"
	case GradeInformational:
		return "informational"
	case GradeOracle:
		return "oracle"
	default:
		return "invalid"
	}
}

func (g Grade) Valid() bool {
	return g == GradeNone || g == GradeInformational || g == GradeOracle
}

package oracle

import "math/overflow"

// MulDiv returns floor(a*b/den). Panics on den==0 or overflow.
// Use this for any shares/index/notional path — do not write a*b/c in int64.
func MulDiv(a, b, den int64) int64 {
	if den == 0 {
		panic("oracle: division by zero")
	}
	prod, ok := overflow.Mul64(a, b)
	if !ok {
		panic("oracle: multiplication overflow")
	}
	quot, ok := overflow.Div64(prod, den)
	if !ok {
		panic("oracle: division overflow")
	}
	return quot
}

package oracle

import "math/overflow"

// MedianInt64 returns the median of xs. The input is not mutated.
// Even length: floor average of the two central values.
func MedianInt64(xs []int64) int64 {
	n := len(xs)
	if n == 0 {
		panic("oracle: empty median")
	}
	ys := make([]int64, n)
	copy(ys, xs)
	for i := 1; i < n; i++ {
		v := ys[i]
		j := i
		for j > 0 && ys[j-1] > v {
			ys[j] = ys[j-1]
			j--
		}
		ys[j] = v
	}
	if n%2 == 1 {
		return ys[n/2]
	}
	sum, ok := overflow.Add64(ys[n/2-1], ys[n/2])
	if !ok {
		panic("oracle: median overflow")
	}
	mid, ok := overflow.Div64(sum, 2)
	if !ok {
		panic("oracle: median overflow")
	}
	return mid
}

package oracle

// Quote is a fail-closed price observation. Fields are unexported so callers
// cannot stamp GradeOracle onto a handmade value.
type Quote struct {
	pair       string
	tick       int32
	liquidity  string
	observedAt int64
	windowSec  uint32
	grade      Grade
	source     string
	err        string
}

const (
	SourceNone   = "none"
	SourceManual = "manual"
	SourceGnoswap = "gnoswap"
)

// None returns a Quote that any RequireAtLeast call will reject.
func None(pair, reason string) Quote {
	if reason == "" {
		reason = "no quote"
	}
	return Quote{
		pair:   pair,
		grade:  GradeNone,
		source: SourceNone,
		err:    reason,
	}
}

// Informational returns a non-credit quote. grade is forced to Informational
// even if the caller passes Oracle — v1 never emits credit-grade quotes.
func Informational(pair string, tick int32, liquidity string, observedAt int64, windowSec uint32, source string) Quote {
	if source == "" {
		source = SourceManual
	}
	return Quote{
		pair:       pair,
		tick:       tick,
		liquidity:  liquidity,
		observedAt: observedAt,
		windowSec:  windowSec,
		grade:      GradeInformational,
		source:     source,
	}
}

func (q Quote) Pair() string       { return q.pair }
func (q Quote) Tick() int32        { return q.tick }
func (q Quote) Liquidity() string  { return q.liquidity }
func (q Quote) ObservedAt() int64  { return q.observedAt }
func (q Quote) WindowSec() uint32  { return q.windowSec }
func (q Quote) Grade() Grade       { return q.grade }
func (q Quote) Source() string     { return q.source }
func (q Quote) Err() string        { return q.err }

func (q Quote) OK() bool {
	return q.grade != GradeNone && q.err == ""
}

// RequireAtLeast panics unless q.OK() and q.Grade >= min.
// Lending liquidation must call RequireAtLeast(GradeOracle) — which v1
// cannot satisfy, by construction.
func (q Quote) RequireAtLeast(min Grade) {
	if !min.Valid() || min == GradeNone {
		panic("oracle: invalid minimum grade")
	}
	if q.err != "" {
		panic("oracle: " + q.err)
	}
	if q.grade < min {
		panic("oracle: grade " + q.grade.String() + " below " + min.String())
	}
}

// RequireCredit is RequireAtLeast(GradeOracle).
func RequireCredit(q Quote) {
	q.RequireAtLeast(GradeOracle)
}

package oracle

// UsdScale is micro-USD: 1 USD = 1_000_000. Structural, not a credit param.
const UsdScale int64 = 1_000_000

const SourcePush = "push"

// UsdQuote is a fail-closed USD observation. Not a Uniswap tick.
// v1 never stamps GradeOracle.
type UsdQuote struct {
	symbol     string
	usdMicro   int64
	observedAt int64
	nFresh     int
	grade      Grade
	source     string
	err        string
}

func UsdNone(symbol, reason string) UsdQuote {
	if reason == "" {
		reason = "no quote"
	}
	return UsdQuote{
		symbol: symbol,
		grade:  GradeNone,
		source: SourceNone,
		err:    reason,
	}
}

func UsdInformational(symbol string, usdMicro, observedAt int64, nFresh int) UsdQuote {
	return UsdQuote{
		symbol:     symbol,
		usdMicro:   usdMicro,
		observedAt: observedAt,
		nFresh:     nFresh,
		grade:      GradeInformational,
		source:     SourcePush,
	}
}

func (q UsdQuote) Symbol() string    { return q.symbol }
func (q UsdQuote) UsdMicro() int64   { return q.usdMicro }
func (q UsdQuote) ObservedAt() int64 { return q.observedAt }
func (q UsdQuote) NFresh() int       { return q.nFresh }
func (q UsdQuote) Grade() Grade      { return q.grade }
func (q UsdQuote) Source() string    { return q.source }
func (q UsdQuote) Err() string       { return q.err }

func (q UsdQuote) OK() bool {
	return q.grade != GradeNone && q.err == ""
}

func (q UsdQuote) RequireAtLeast(min Grade) {
	if !min.Valid() || min == GradeNone {
		panic("oracle: invalid minimum grade")
	}
	if q.err != "" {
		panic("oracle: " + q.err)
	}
	if q.grade < min {
		panic("oracle: grade " + q.grade.String() + " below " + min.String())
	}
}

func RequireUsdCredit(q UsdQuote) {
	q.RequireAtLeast(GradeOracle)
}

package oracle

import (
	"time"

	"chain"
	"chain/runtime/unsafe"

	poracle "gno.land/p/g18ugne5ng6eylkca4mqeet9luj0xaykp84sh2cf/oracle/v4"
)

const (
	maxFeeds   = 16
	maxPairLen = 128
)

type feed struct {
	pair      string
	tick      int32
	liquidity string
	windowSec uint32
	maxAgeSec int64
	updatedAt int64
}

var (
	admin address
	feeds []feed
)

func init() {
	c := unsafe.OriginCaller()
	if c.IsValid() {
		admin = c
	}
}

func Admin() address {
	return admin
}

func FeedCount() int {
	return len(feeds)
}

func requireAdmin(cur realm) {
	if !cur.IsCurrent() {
		panic("oracle: invalid realm")
	}
	caller := cur.Previous().Address()
	if !admin.IsValid() {
		if !caller.IsValid() {
			panic("oracle: no admin")
		}
		admin = caller
		return
	}
	if caller != admin {
		panic("oracle: admin only")
	}
}

func validPair(pair string) bool {
	if pair == "" || len(pair) > maxPairLen {
		return false
	}
	for i := 0; i < len(pair); i++ {
		c := pair[i]
		ok := (c >= 'a' && c <= 'z') ||
			(c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') ||
			c == '_' || c == '-' || c == '/' || c == '|' || c == ':' || c == '.'
		if !ok {
			return false
		}
	}
	return true
}

func find(pair string) int {
	for i := 0; i < len(feeds); i++ {
		if feeds[i].pair == pair {
			return i
		}
	}
	return -1
}

// TransferAdmin rotates the admin. Crossing; caller must be current admin.
func TransferAdmin(cur realm, next address) {
	requireAdmin(cur)
	if !next.IsValid() {
		panic("oracle: invalid admin")
	}
	prev := admin
	admin = next
	chain.Emit("AdminChange", "old", prev.String(), "new", next.String())
}

// SetManualFeed upserts a manual observation.
// Grade is always Informational (v1 never stamps Oracle).
func SetManualFeed(cur realm, pair string, tick int32, liquidity string, windowSec uint32, maxAgeSec int64) {
	requireAdmin(cur)
	if !validPair(pair) {
		panic("oracle: invalid pair")
	}
	if windowSec == 0 {
		panic("oracle: windowSec required")
	}
	if maxAgeSec < 1 {
		panic("oracle: maxAgeSec required")
	}
	if len(liquidity) > 128 {
		panic("oracle: liquidity too long")
	}
	now := time.Now().Unix()
	i := find(pair)
	f := feed{
		pair:      pair,
		tick:      tick,
		liquidity: liquidity,
		windowSec: windowSec,
		maxAgeSec: maxAgeSec,
		updatedAt: now,
	}
	if i < 0 {
		if len(feeds) >= maxFeeds {
			panic("oracle: feed cap")
		}
		feeds = append(feeds, f)
	} else {
		feeds[i] = f
	}
	chain.Emit("ManualFeed", "pair", pair)
}

// RemoveFeed deletes a pair.
func RemoveFeed(cur realm, pair string) {
	requireAdmin(cur)
	i := find(pair)
	if i < 0 {
		panic("oracle: unknown pair")
	}
	feeds = append(feeds[:i], feeds[i+1:]...)
	chain.Emit("RemoveFeed", "pair", pair)
}

// Consult is a read. Missing or stale feeds return GradeNone.
func Consult(pair string) poracle.Quote {
	if !validPair(pair) {
		return poracle.None(pair, "invalid pair")
	}
	i := find(pair)
	if i < 0 {
		return poracle.None(pair, "unknown pair")
	}
	f := feeds[i]
	now := time.Now().Unix()
	if f.updatedAt <= 0 || now-f.updatedAt > f.maxAgeSec {
		return poracle.None(pair, "stale")
	}
	return poracle.Informational(pair, f.tick, f.liquidity, f.updatedAt, f.windowSec, poracle.SourceManual)
}

// MustInformational panics unless Consult is at least informational.
func MustInformational(pair string) poracle.Quote {
	q := Consult(pair)
	q.RequireAtLeast(poracle.GradeInformational)
	return q
}

package oracle

import (
	"strconv"
	"time"

	poracle "gno.land/p/g18ugne5ng6eylkca4mqeet9luj0xaykp84sh2cf/oracle/v4"
)

func Render(_ string) string {
	out := "# Oracle\n\n"
	out += "Fail-closed USD quote registry. **Informational only. Not credit-grade.** "
	out += "`RequireCredit` / `RequireUsdCredit` panic until a future feed assigns `GradeOracle`.\n\n"
	out += "- admin: `" + admin.String() + "`\n"
	out += "- feeds: " + strconv.Itoa(len(feeds)) + "/" + strconv.Itoa(maxFeeds) + "\n\n"
	out += "## Manual ticks\n\n"
	if len(feeds) == 0 {
		out += "_No manual feeds._\n\n"
	} else {
		out += "| pair | tick | window | maxAge | grade |\n|---|---|---|---|---|\n"
		for i := 0; i < len(feeds); i++ {
			f := feeds[i]
			q := Consult(f.pair)
			out += "| `" + f.pair + "` | " + strconv.Itoa(int(f.tick)) +
				" | " + strconv.Itoa(int(f.windowSec)) +
				" | " + strconv.Itoa(int(f.maxAgeSec)) +
				" | " + q.Grade().String() + " |\n"
		}
		out += "\n"
	}
	out += "## USD push (external)\n\n"
	out += "micro-USD scale " + strconv.Itoa(int(poracle.UsdScale)) + ". Median of fresh publishers. **Informational only.**\n\n"
	if len(usdFeeds) == 0 {
		out += "_No USD feeds._\n"
		return out
	}
	out += "| symbol | pubs | minFresh | maxAge | usdMicro | grade |\n|---|---|---|---|---|---|\n"
	for i := 0; i < len(usdFeeds); i++ {
		f := usdFeeds[i]
		u := ConsultUsd(f.symbol)
		out += "| `" + f.symbol + "` | " + strconv.Itoa(len(f.pubs)) +
			" | " + strconv.Itoa(f.minFresh) +
			" | " + strconv.Itoa(int(f.maxAgeSec)) +
			" | " + strconv.Itoa(int(u.UsdMicro())) +
			" | " + u.Grade().String() + " |\n"
	}
	out += "\n## USD publishers (last post)\n\n"
	out += "| symbol | publisher | usdMicro | observedAt | postedAt | slot |\n|---|---|---|---|---|---|\n"
	now := time.Now().Unix()
	for i := 0; i < len(usdFeeds); i++ {
		f := usdFeeds[i]
		for j := 0; j < len(f.pubs); j++ {
			p := f.posts[j]
			slot := "empty"
			if p.usdMicro > 0 && p.postedAt > 0 {
				if now-p.postedAt <= f.maxAgeSec && now-p.observedAt <= f.maxAgeSec {
					slot = "fresh"
				} else {
					slot = "stale"
				}
			}
			out += "| `" + f.symbol + "` | `" + f.pubs[j].String() + "` | " +
				strconv.Itoa(int(p.usdMicro)) + " | " +
				strconv.Itoa(int(p.observedAt)) + " | " +
				strconv.Itoa(int(p.postedAt)) + " | " + slot + " |\n"
		}
	}
	return out
}

package oracle

import (
	"time"

	"chain"

	poracle "gno.land/p/g18ugne5ng6eylkca4mqeet9luj0xaykp84sh2cf/oracle/v4"
)

const (
	maxUsdFeeds    = 8
	maxPublishers  = 8
	maxSymbolLen   = 32
	maxUsdMicro    = int64(1_000_000) * poracle.UsdScale // $1e6 cap, not a credit LTV
)

type usdPost struct {
	usdMicro   int64
	postedAt   int64
	observedAt int64
}

type usdFeed struct {
	symbol     string
	maxAgeSec  int64
	minFresh   int
	pubs       []address
	posts      []usdPost
}

var usdFeeds []usdFeed

func UsdFeedCount() int {
	return len(usdFeeds)
}

func validSymbol(sym string) bool {
	if sym == "" || len(sym) > maxSymbolLen {
		return false
	}
	hyphen := 0
	for i := 0; i < len(sym); i++ {
		c := sym[i]
		if c == '-' {
			hyphen++
			continue
		}
		ok := (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
		if !ok {
			return false
		}
	}
	return hyphen == 1 && sym[0] != '-' && sym[len(sym)-1] != '-'
}

func findUsd(sym string) int {
	for i := 0; i < len(usdFeeds); i++ {
		if usdFeeds[i].symbol == sym {
			return i
		}
	}
	return -1
}

func findPub(f usdFeed, who address) int {
	for i := 0; i < len(f.pubs); i++ {
		if f.pubs[i] == who {
			return i
		}
	}
	return -1
}

// AddUsdFeed registers an EXTERNAL USD symbol (e.g. BTC-USD). Informational only.
func AddUsdFeed(cur realm, symbol string, maxAgeSec int64, minFresh int) {
	requireAdmin(cur)
	if !validSymbol(symbol) {
		panic("oracle: invalid symbol")
	}
	if maxAgeSec < 1 {
		panic("oracle: maxAgeSec required")
	}
	if minFresh < 1 || minFresh > maxPublishers {
		panic("oracle: minFresh out of range")
	}
	if findUsd(symbol) >= 0 {
		panic("oracle: symbol exists")
	}
	if len(usdFeeds) >= maxUsdFeeds {
		panic("oracle: usd feed cap")
	}
	usdFeeds = append(usdFeeds, usdFeed{
		symbol:    symbol,
		maxAgeSec: maxAgeSec,
		minFresh:  minFresh,
	})
	chain.Emit("UsdFeedAdd", "symbol", symbol)
}

func RemoveUsdFeed(cur realm, symbol string) {
	requireAdmin(cur)
	i := findUsd(symbol)
	if i < 0 {
		panic("oracle: unknown symbol")
	}
	usdFeeds = append(usdFeeds[:i], usdFeeds[i+1:]...)
	chain.Emit("UsdFeedRemove", "symbol", symbol)
}

func AddPublisher(cur realm, symbol string, who address) {
	requireAdmin(cur)
	if !who.IsValid() {
		panic("oracle: invalid publisher")
	}
	i := findUsd(symbol)
	if i < 0 {
		panic("oracle: unknown symbol")
	}
	if findPub(usdFeeds[i], who) >= 0 {
		panic("oracle: publisher exists")
	}
	if len(usdFeeds[i].pubs) >= maxPublishers {
		panic("oracle: publisher cap")
	}
	usdFeeds[i].pubs = append(usdFeeds[i].pubs, who)
	usdFeeds[i].posts = append(usdFeeds[i].posts, usdPost{})
	chain.Emit("UsdPublisherAdd", "symbol", symbol, "who", who.String())
}

func RemovePublisher(cur realm, symbol string, who address) {
	requireAdmin(cur)
	i := findUsd(symbol)
	if i < 0 {
		panic("oracle: unknown symbol")
	}
	j := findPub(usdFeeds[i], who)
	if j < 0 {
		panic("oracle: unknown publisher")
	}
	f := usdFeeds[i]
	f.pubs = append(f.pubs[:j], f.pubs[j+1:]...)
	f.posts = append(f.posts[:j], f.posts[j+1:]...)
	usdFeeds[i] = f
	chain.Emit("UsdPublisherRemove", "symbol", symbol, "who", who.String())
}

// PostUsd is called by an allowlisted publisher EOA. Auth = MsgCall address.
// sig bytes are not accepted: Gno cannot ecrecover; do not pretend.
func PostUsd(cur realm, symbol string, usdMicro, observedAt int64) {
	if !cur.IsCurrent() {
		panic("oracle: invalid realm")
	}
	caller := cur.Previous().Address()
	i := findUsd(symbol)
	if i < 0 {
		panic("oracle: unknown symbol")
	}
	j := findPub(usdFeeds[i], caller)
	if j < 0 {
		panic("oracle: not a publisher")
	}
	if usdMicro < 1 || usdMicro > maxUsdMicro {
		panic("oracle: usdMicro out of range")
	}
	now := time.Now().Unix()
	if observedAt < 0 || observedAt > now {
		panic("oracle: observedAt invalid")
	}
	usdFeeds[i].posts[j] = usdPost{
		usdMicro:   usdMicro,
		postedAt:   now,
		observedAt: observedAt,
	}
	chain.Emit("UsdPost", "symbol", symbol, "who", caller.String())
}

// ConsultUsd returns median of fresh publisher posts, or GradeNone.
// Always Informational when OK — never GradeOracle.
func ConsultUsd(symbol string) poracle.UsdQuote {
	if !validSymbol(symbol) {
		return poracle.UsdNone(symbol, "invalid symbol")
	}
	i := findUsd(symbol)
	if i < 0 {
		return poracle.UsdNone(symbol, "unknown symbol")
	}
	f := usdFeeds[i]
	now := time.Now().Unix()
	fresh := make([]int64, 0, len(f.posts))
	var newestObs int64
	for k := 0; k < len(f.posts); k++ {
		p := f.posts[k]
		if p.usdMicro < 1 || p.postedAt < 1 {
			continue
		}
		if now-p.postedAt > f.maxAgeSec || now-p.observedAt > f.maxAgeSec {
			continue
		}
		fresh = append(fresh, p.usdMicro)
		if p.observedAt > newestObs {
			newestObs = p.observedAt
		}
	}
	if len(fresh) < f.minFresh {
		return poracle.UsdNone(symbol, "quorum")
	}
	med := poracle.MedianInt64(fresh)
	return poracle.UsdInformational(symbol, med, newestObs, len(fresh))
}

package oracle

// Grade is the trust level of a Quote.
//
// None: missing, stale, or error — must not drive any protocol action.
// Informational: a price exists (manual or DEX TWAP) — UI only, not liquidation.
// Oracle: reserved for a future credit-grade feed. This package does not
// assign Oracle in v1; RequireAtLeast(Oracle) therefore fail-closes.
type Grade int

const (
	GradeNone Grade = iota
	GradeInformational
	GradeOracle
)

func (g Grade) String() string {
	switch g {
	case GradeNone:
		return "none"
	case GradeInformational:
		return "informational"
	case GradeOracle:
		return "oracle"
	default:
		return "invalid"
	}
}

func (g Grade) Valid() bool {
	return g == GradeNone || g == GradeInformational || g == GradeOracle
}

package oracle

import "math/overflow"

// MulDiv returns floor(a*b/den). Panics on den==0 or overflow.
// Use this for any shares/index/notional path — do not write a*b/c in int64.
func MulDiv(a, b, den int64) int64 {
	if den == 0 {
		panic("oracle: division by zero")
	}
	prod, ok := overflow.Mul64(a, b)
	if !ok {
		panic("oracle: multiplication overflow")
	}
	quot, ok := overflow.Div64(prod, den)
	if !ok {
		panic("oracle: division overflow")
	}
	return quot
}

// BpsAbs is |a-b|*10000/b. Ops bound helper, not LTV. Panics if b==0.
func BpsAbs(a, b int64) int64 {
	if b == 0 {
		panic("oracle: bps denominator")
	}
	diff := a - b
	if diff < 0 {
		diff = -diff
	}
	return MulDiv(diff, 10000, b)
}

package oracle

import "math/overflow"

// MedianInt64 returns the median of xs. The input is not mutated.
// Even length: floor average of the two central values.
func MedianInt64(xs []int64) int64 {
	n := len(xs)
	if n == 0 {
		panic("oracle: empty median")
	}
	ys := make([]int64, n)
	copy(ys, xs)
	for i := 1; i < n; i++ {
		v := ys[i]
		j := i
		for j > 0 && ys[j-1] > v {
			ys[j] = ys[j-1]
			j--
		}
		ys[j] = v
	}
	if n%2 == 1 {
		return ys[n/2]
	}
	sum, ok := overflow.Add64(ys[n/2-1], ys[n/2])
	if !ok {
		panic("oracle: median overflow")
	}
	mid, ok := overflow.Div64(sum, 2)
	if !ok {
		panic("oracle: median overflow")
	}
	return mid
}

package oracle

// Quote is a fail-closed price observation. Fields are unexported so callers
// cannot stamp GradeOracle onto a handmade value.
type Quote struct {
	pair       string
	tick       int32
	liquidity  string
	observedAt int64
	windowSec  uint32
	grade      Grade
	source     string
	err        string
}

const (
	SourceNone   = "none"
	SourceManual = "manual"
	SourceGnoswap = "gnoswap"
)

// None returns a Quote that any RequireAtLeast call will reject.
func None(pair, reason string) Quote {
	if reason == "" {
		reason = "no quote"
	}
	return Quote{
		pair:   pair,
		grade:  GradeNone,
		source: SourceNone,
		err:    reason,
	}
}

// Informational returns a non-credit quote. grade is forced to Informational
// even if the caller passes Oracle — v1 never emits credit-grade quotes.
func Informational(pair string, tick int32, liquidity string, observedAt int64, windowSec uint32, source string) Quote {
	if source == "" {
		source = SourceManual
	}
	return Quote{
		pair:       pair,
		tick:       tick,
		liquidity:  liquidity,
		observedAt: observedAt,
		windowSec:  windowSec,
		grade:      GradeInformational,
		source:     source,
	}
}

func (q Quote) Pair() string       { return q.pair }
func (q Quote) Tick() int32        { return q.tick }
func (q Quote) Liquidity() string  { return q.liquidity }
func (q Quote) ObservedAt() int64  { return q.observedAt }
func (q Quote) WindowSec() uint32  { return q.windowSec }
func (q Quote) Grade() Grade       { return q.grade }
func (q Quote) Source() string     { return q.source }
func (q Quote) Err() string        { return q.err }

func (q Quote) OK() bool {
	return q.grade != GradeNone && q.err == ""
}

// RequireAtLeast panics unless q.OK() and q.Grade >= min.
// Lending liquidation must call RequireAtLeast(GradeOracle) — which v1
// cannot satisfy, by construction.
func (q Quote) RequireAtLeast(min Grade) {
	if !min.Valid() || min == GradeNone {
		panic("oracle: invalid minimum grade")
	}
	if q.err != "" {
		panic("oracle: " + q.err)
	}
	if q.grade < min {
		panic("oracle: grade " + q.grade.String() + " below " + min.String())
	}
}

// RequireCredit is RequireAtLeast(GradeOracle).
func RequireCredit(q Quote) {
	q.RequireAtLeast(GradeOracle)
}

